package handlers

func init() {
	adminTemplates["static_delivery"] = adminLayoutStart + staticDeliveryBody + cloudflareManagementScript + adminLayoutEnd
}

const staticDeliveryBody = `
<style>
.cf-management{max-width:1280px}.cf-toolbar{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:24px}.cf-toolbar h1,.cf-toolbar h2,.cf-dialog h2,.cf-dialog h3{margin:0}.cf-muted{color:var(--text-muted);line-height:1.65}.cf-search{max-width:420px;margin-bottom:16px}.cf-management input,.cf-dialog input,.cf-dialog select{width:100%;min-height:44px;padding:10px 12px;background:var(--bg);border:1px solid var(--border);border-radius:6px;color:var(--text)}.cf-management button,.cf-dialog button{min-height:44px}.cf-table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:8px}.cf-table{width:100%;border-collapse:collapse;text-align:left}.cf-table th{background:var(--bg-secondary);color:var(--text-muted);font-size:13px;font-weight:600}.cf-table td,.cf-table th{padding:16px 20px;border-bottom:1px solid var(--border);vertical-align:top}.cf-table tr:last-child td{border-bottom:0}.cf-table td{overflow-wrap:anywhere}.cf-id{display:block;font-size:13px;line-height:1.6;color:var(--text-muted);overflow-wrap:anywhere}.cf-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.cf-actions form{margin:0}.cf-actions .btn{white-space:nowrap}.cf-empty{padding:40px 24px;text-align:center;color:var(--text-muted)}.cf-note{margin:16px 0;padding:12px 16px;border-left:3px solid var(--primary);background:var(--bg-secondary);line-height:1.65}.cf-dialog{width:min(1180px,calc(100% - 32px));max-height:90dvh;box-sizing:border-box;padding:0;border:1px solid var(--border);border-radius:10px;background:var(--bg);color:var(--text);box-shadow:0 24px 80px #0006}.cf-dialog-small{width:min(600px,calc(100% - 32px))}.cf-dialog::backdrop{background:#050a16b8}.cf-dialog-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding:24px;border-bottom:1px solid var(--border)}.cf-dialog-content{padding:24px;overflow-wrap:anywhere}.cf-dialog label{display:block;font-size:14px;margin-bottom:8px}.cf-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:20px 0}.cf-fields .cf-wide{grid-column:1/-1}.cf-dialog input[type=checkbox]{width:18px;min-height:18px;flex:none}.cf-consent{display:flex!important;gap:10px;align-items:flex-start;line-height:1.6}.cf-dialog input[readonly],.cf-dialog select:disabled{opacity:.65}.cf-editor{margin-top:24px;padding:24px;border:1px solid var(--border);border-radius:8px;background:var(--bg-secondary)}.cf-danger{color:#e47777!important}.cf-close{background:transparent;border:0;color:var(--text-muted);font-size:24px;padding:0 10px;cursor:pointer}.cf-management :focus-visible,.cf-dialog :focus-visible{outline:2px solid var(--primary);outline-offset:3px}.cf-dialog details{margin-top:20px}.cf-dialog summary{cursor:pointer;padding:12px 0}.cf-dialog .cf-row-options{margin:0}.cf-row-options form{margin:12px 0}.cf-dialog [hidden],.cf-management [hidden]{display:none!important}.cf-footer{margin-top:24px}.cf-status{display:inline-block;padding:4px 8px;font-size:13px;border:1px solid var(--border);border-radius:4px}.cf-status-ready{color:#57c79d}.cf-account-name{font-weight:600}.cf-dialog .cf-table{min-width:720px}@media(max-width:640px){.cf-toolbar{align-items:flex-start}.cf-toolbar h1{font-size:26px}.cf-table td,.cf-table th{padding:12px}.cf-management>.cf-table-wrap>.cf-table{min-width:700px}.cf-dialog-header,.cf-dialog-content{padding:16px}.cf-fields{grid-template-columns:minmax(0,1fr);gap:16px}.cf-editor{padding:16px}.cf-toolbar .btn{flex:none}.cf-dialog{width:calc(100% - 16px);max-height:94dvh}.cf-search{max-width:none}}
</style>
<div class="cf-management">
 <div class="cf-toolbar"><div><h1>{{.CF.title}}</h1><p class="cf-muted">{{.CF.intro}}</p></div>{{if not .ModuleError}}<button class="btn btn-primary" id="cf-add-account" type="button">{{.CF.addAccount}}</button>{{end}}</div>
 {{if .Saved}}<div class="cf-note" role="status">{{.CF.saved}}</div>{{end}}
 {{if .Notice}}<div class="cf-note" role="alert">{{.Notice}}</div>{{end}}
 {{if .ModuleError}}<div class="cf-note" role="alert">{{.ModuleError}}</div></div>{{else}}
 <label class="cf-id" for="cf-account-search">{{.CF.search}}</label><input id="cf-account-search" class="cf-search" type="search" placeholder="{{.CF.search}}">
 <div class="cf-table-wrap"><table id="cloudflare-accounts" class="cf-table"><thead><tr><th scope="col">{{.CF.account}}</th><th scope="col">{{.CF.workers}}</th><th scope="col">{{.CF.connection}}</th><th scope="col">{{.CF.status}}</th><th scope="col">{{.CF.actions}}</th></tr></thead><tbody>
 {{range .Accounts}}<tr data-cf-account-row data-search="{{.Name}} {{.AccountID}}"><td><span class="cf-account-name">{{.Name}}</span><span class="cf-id">{{.AccountID}}</span>{{if .Remark}}<span class="cf-id">{{.Remark}}</span>{{end}}</td><td>{{len .Workers}}</td><td><span>{{if .Verification.Readable}}{{$.CF.readable}}{{else}}{{$.CF.unverified}}{{end}}</span><span class="cf-id">{{if .Verification.WriteVerified}}{{$.CF.writeVerified}}{{else}}{{$.CF.writeUnverified}}{{end}}</span></td><td><span class="cf-status">{{index $.CF .Status}}</span></td><td><div class="cf-actions"><button type="button" class="btn btn-secondary" data-cf-account="{{.ID.Hex}}">{{$.CF.details}}</button><button type="button" class="btn btn-secondary cf-danger" data-cf-delete-account="{{.ID.Hex}}">{{$.CF.delete}}</button></div></td></tr>{{else}}<tr><td colspan="5" class="cf-empty">{{.CF.emptyAccounts}}</td></tr>{{end}}
 </tbody></table><p class="cf-empty" id="cf-account-no-match" hidden>{{.CF.noMatch}}</p></div>
 <p class="cf-muted cf-footer"><a href="/cm/static-delivery/publish">{{.CF.publishHistory}}</a></p>
</div>
<dialog id="cf-add-account-dialog" class="cf-dialog cf-dialog-small" aria-labelledby="cf-add-title">
 <header class="cf-dialog-header"><h2 id="cf-add-title">{{.CF.addAccount}}</h2><button class="cf-close" type="button" data-cf-close aria-label="{{.CF.close}}">×</button></header>
 <div class="cf-dialog-content"><form method="post" action="/cm/static-delivery/accounts">{{.CSRFField}}
  <div class="cf-fields"><div><label for="account-name">{{.CF.accountName}}</label><input id="account-name" name="name" required maxlength="200"></div><div><label for="account-id">Cloudflare Account ID</label><input id="account-id" name="account_id" pattern="[a-fA-F0-9]{32}" required autocomplete="off"></div><div class="cf-wide"><label for="account-token">API Token</label><input id="account-token" type="password" name="token" required autocomplete="new-password"></div><div class="cf-wide"><label for="account-remark">{{.CF.remark}}</label><input id="account-remark" name="remark" maxlength="2000"></div></div>
  <p class="cf-muted">{{.CF.tokenHelp}}</p><p class="cf-id">{{.CF.storageHelp}}</p><div class="cf-actions"><button type="button" data-cf-close class="btn btn-secondary">{{.CF.cancel}}</button><button class="btn btn-primary">{{.CF.save}}</button></div>
 </form></div>
</dialog>
<dialog id="cf-account-dialog" class="cf-dialog" aria-labelledby="cf-account-title">
 <header class="cf-dialog-header"><div><h2 id="cf-account-title"></h2><span id="cf-account-id" class="cf-id"></span></div><button class="cf-close" type="button" data-cf-close aria-label="{{.CF.close}}">×</button></header>
 <div class="cf-dialog-content">
  {{if .Notice}}<div class="cf-note" role="alert">{{.Notice}}</div>{{end}}
  <div class="cf-toolbar"><h3>{{.CF.workerList}}</h3><button type="button" id="cf-add-worker" class="btn btn-primary">{{.CF.addWorker}}</button></div>
  <label class="cf-id" for="cf-worker-search">{{.CF.workerSearch}}</label><input id="cf-worker-search" class="cf-search" type="search" placeholder="{{.CF.workerSearch}}">
  <div class="cf-table-wrap"><table class="cf-table"><thead><tr><th>{{.CF.displayName}}</th><th>{{.CF.origin}}</th><th>{{.CF.environment}}</th><th>{{.CF.status}}</th><th>{{.CF.actions}}</th></tr></thead><tbody id="cf-worker-rows"></tbody></table></div>
  <section id="cf-worker-editor" class="cf-editor" hidden><h3 id="cf-worker-editor-title"></h3>
   <form method="post" action="/cm/static-delivery/targets" id="cf-worker-form">{{.CSRFField}}
    <input type="hidden" id="cf-worker-account" name="account_ref"><input type="hidden" name="expected_config_revision" id="cf-worker-revision"><input type="hidden" name="expected_management_revision" id="cf-worker-management-revision"><input type="hidden" name="environment" id="cf-worker-environment-value">
    <div class="cf-fields"><div><label for="cf-worker-display-name">{{.CF.displayName}}</label><input id="cf-worker-display-name" name="name" required maxlength="200"></div><div><label for="cf-worker-name">{{.CF.workerName}}</label><input id="cf-worker-name" name="worker_name" required pattern="[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?"></div><div><label for="cf-worker-environment">{{.CF.environment}}</label><select id="cf-worker-environment"><option value="test">{{.CF.test}}</option><option value="production">{{.CF.production}}</option></select></div><div><label for="cf-worker-origin">{{.CF.origin}}</label><input id="cf-worker-origin" name="public_origin" type="url" placeholder="{{.CF.optionalOrigin}}"></div></div>
    <p class="cf-muted" id="cf-worker-help"></p><div class="cf-actions"><button type="button" id="cf-worker-cancel" class="btn btn-secondary">{{.CF.cancel}}</button><button class="btn btn-primary">{{.CF.saveWorker}}</button></div>
   </form>
  </section>
  <section id="cf-worker-delete" class="cf-editor" hidden><h3>{{.CF.deleteWorkerTitle}}</h3><p id="cf-worker-delete-name"></p><p class="cf-muted">{{.CF.deleteWorkerHelp}}</p><form method="post" action="/cm/static-delivery/targets" id="cf-worker-delete-form">{{.CSRFField}}<input type="hidden" name="account_ref" id="cf-worker-delete-account"><label class="cf-consent"><input type="checkbox" name="confirm_delete" value="yes" required> {{.CF.deleteConsent}}</label><div class="cf-actions"><button type="button" id="cf-worker-delete-cancel" class="btn btn-secondary">{{.CF.cancel}}</button><button class="btn btn-primary">{{.CF.deleteConfirm}}</button></div></form></section>
  <details id="cf-account-settings"><summary>{{.CF.accountSettings}}</summary><p class="cf-id" id="cf-credential-status"></p><div class="cf-actions">
   <form method="post" action="/cm/static-delivery/accounts" id="cf-account-verify">{{.CSRFField}}<label for="cf-verify-worker-scope">{{.CF.workerScope}}</label><input id="cf-verify-worker-scope" name="worker_name" autocomplete="off"><button class="btn btn-secondary">{{.CF.verifyAccount}}</button></form>
   <form method="post" action="/cm/static-delivery/accounts" id="cf-account-toggle">{{.CSRFField}}<button class="btn btn-secondary" id="cf-account-toggle-label"></button></form>
  </div>
  <form method="post" action="/cm/static-delivery/accounts" id="cf-account-rotate">{{.CSRFField}}<div class="cf-fields"><div><label for="cf-new-token">{{.CF.newToken}}</label><input id="cf-new-token" type="password" name="token" required autocomplete="new-password"></div><div><label for="cf-worker-scope">{{.CF.workerScope}}</label><input id="cf-worker-scope" name="worker_name"></div></div><button class="btn btn-secondary">{{.CF.rotate}}</button></form>
  </details>
 </div>
</dialog>
<dialog id="cf-delete-account-dialog" class="cf-dialog cf-dialog-small" aria-labelledby="cf-delete-title"><header class="cf-dialog-header"><h2 id="cf-delete-title">{{.CF.deleteAccountTitle}}</h2><button class="cf-close" type="button" data-cf-close aria-label="{{.CF.close}}">×</button></header><div class="cf-dialog-content"><p id="cf-delete-account-name"></p><p class="cf-muted">{{.CF.deleteAccountHelp}}</p><form method="post" action="/cm/static-delivery/accounts" id="cf-delete-account-form">{{.CSRFField}}<label class="cf-consent"><input type="checkbox" name="confirm_delete" value="yes" required> {{.CF.deleteConsent}}</label><div class="cf-actions"><button type="button" data-cf-close class="btn btn-secondary">{{.CF.cancel}}</button><button class="btn btn-primary">{{.CF.deleteConfirm}}</button></div></form></div></dialog>
{{end}}
`
